from typing import List

def tri(n: int) -> List[int]:
    """Return the first n+1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [1]
    if n == 1:
        return [1, 3]

    result = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            result.append(1 + i // 2)
        else:
            # For odd i, we need the next even term (i+1) which is 1 + (i+1)//2
            next_even_term = 1 + (i + 1) // 2
            result.append(result[-1] + result[-2] + next_even_term)

    return result

